(()=>{const {t,esc,request,roles,status}=F;let state={connected:false,events:RACE_EVENTS};function render(){const picker=document.querySelector('#publicRace'),selected=picker.value||new URLSearchParams(location.search).get('event');picker.innerHTML=state.events.map(e=>`<option value="${esc(e.id)}">${esc(I18N.event(e).name)}</option>`).join('');if(state.events.some(e=>e.id===selected))picker.value=selected;const role=document.querySelector('#preferredRole'),chosen=role.value;role.innerHTML=Object.entries(roles).map(([key,name])=>`<option value="${key}">${t(name)}</option>`).join('');if(chosen)role.value=chosen;document.querySelector('#volunteerRoles').innerHTML=Object.entries(roles).map(([key,name],i)=>`<article><b>0${i+1}</b><span>${t(name)}</span></article>`).join('');document.querySelector('#publicNotice').textContent=t(state.connected?'الطلب يحتاج موافقة المنظّم؛ اختيار المهمة لا يؤكد توزيعك.':'هذه معاينة؛ شغّل الخادم لحفظ طلب التطوّع.');document.querySelector('#volunteerForm button[type=submit]').disabled=!state.events.length}F.races().then(s=>{state=s;render()});render();window.addEventListener('languagechange',render);document.querySelector('#volunteerForm').addEventListener('submit',async e=>{e.preventDefault();if(!state.connected)return status('هذه معاينة؛ شغّل الخادم لحفظ طلب التطوّع.',true);const f=new FormData(e.target),b=Object.fromEntries(f);b.qualified=f.has('qualified');b.contactConsent=f.has('contactConsent');b.language=I18N.lang;for(const key of ['availableFrom','availableTo'])b[key]=b[key]?new Date(b[key]).toISOString():null;const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const d=await request('/api/volunteers',{method:'POST',body:JSON.stringify(b)});status(d.message);e.target.reset();render()}catch(err){status(err.message,true)}finally{button.disabled=false}})})();
